  static String anahtar(String metin) => metin
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim()
      .toLowerCase()
      .replaceAll(RegExp(r'[.,!?]+$'), '')
      .trim()
      .replaceAll(RegExp('[\u2019\u2018`]'), "'");

  /// Metnin ses adresi; manifestte yoksa null.
  static String? url(String metin) {
    final dosya = entries[anahtar(metin)];
    return dosya == null ? null : '$taban$dosya';
  }
